  {
    "section": "plan_items",
    "op": "append",
    "planId": "pl_003",
    "entry": {
      "sequence": 1,
      "record_type": "probate",
      "jurisdiction": "Schuylkill County, Pennsylvania",
      "date_range": "1860-1870",
      "repository": "FamilySearch",
      "rationale": "New reference suggests Thomas Flynn died ~1865, not in the 1875–1890 window previously targeted. Schuylkill County probate records (wills and administrations) covering this corrected window are indexed on FamilySearch. An estate filing or will naming Patrick as a son would be direct evidence of parentage. Supersedes the in-progress pli_006, which searched the wrong decade.",
      "fallback_for": null,
      "status": "planned"
    }
  },
  {
    "section": "plan_items",
    "op": "append",
    "planId": "pl_003",
    "entry": {
      "sequence": 2,
      "record_type": "census",
      "jurisdiction": "Schuylkill County, Pennsylvania",
      "date_range": "1870",
      "repository": "FamilySearch",
      "rationale": "If Thomas Flynn died ~1865, he should be absent from the 1870 census. Finding his widow (or no Flynn household matching his profile) would corroborate the earlier death window and may reveal the widow's name — an important FAN lead. If Thomas appears alive in 1870, the death date must be revised again.",
      "fallback_for": null,
      "status": "planned"
    }
  },
  {
    "section": "plan_items",
    "op": "append",
    "planId": "pl_003",
    "entry": {
      "sequence": 3,
      "record_type": "church",
      "jurisdiction": "Pottsville, Schuylkill County, Pennsylvania",
      "date_range": "1860-1870",
      "repository": "FamilySearch",
      "rationale": "The Flynn family was almost certainly Irish Catholic; St. Mary's Catholic Church in Pottsville was active by the 1840s. Sacramental registers (burial/death entries) from the 1860s are partially digitized on FamilySearch and could document Thomas's burial date and place directly, without requiring a will.",
      "fallback_for": null,
      "status": "planned"
    }
  },
  {
    "section": "plan_items",
    "op": "append",
    "planId": "pl_003",
    "entry": {
      "sequence": 4,
      "record_type": "newspaper",
      "jurisdiction": "Schuylkill County, Pennsylvania",
      "date_range": "1862-1868",
      "repository": "other",
      "rationale": "The Miners' Journal (Pottsville) regularly published death notices in the 1860s. Searching for a Thomas Flynn death notice in the ~1862–1868 window (bracketing the ~1865 estimate) could directly establish the death date and may mention survivors, including Patrick. Available via Newspapers.com and the Library of Congress Chronicling America portal.",
      "fallback_for": null,
      "status": "planned"
    }
  },
  {
    "section": "plan_items",
    "op": "append",
    "planId": "pl_003",
    "entry": {
      "sequence": 5,
      "record_type": "tax",
      "jurisdiction": "Schuylkill County, Pennsylvania",
      "date_range": "1860-1870",
      "repository": "FamilySearch",
      "rationale": "Fallback for probate (pli_007): if no will or administration is found, Schuylkill County tax assessment lists for the 1860s can show the last year Thomas Flynn was taxed as a living resident. His disappearance from the rolls — followed by the widow or estate appearing — would bracket the death year. These lists are available on FamilySearch as browse-only image sets.",
      "fallback_for": "pli_007",
      "status": "planned"
    }
  }
]
